import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Component Schema


export type SystemNotificationProps = Record<string, any>;

const SystemNotification: React.FC<SystemNotificationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  primaryColor = "#2d1b1b",
  accentColor = "#ea4335",
  textColor = "#3f1d1d",
  badgeText = "1",
  labelText = "1 System Alert",
  durationInSeconds = 5,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive Sizing
  const iconSize = Math.min(width, height) * 0.4;
  const unitHeight = iconSize * 0.25;
  const unitWidth = iconSize * 0.8;
  const unitGap = iconSize * 0.05;
  const badgeSize = iconSize * 0.35;

  // Animation Utilities
  const createSpring = (delay: number) =>
    spring({
      frame: frame - delay,
      fps,
      config: { damping: 12, stiffness: 100 },
    });

  // Animations
  // 1. Server Units (Bottom to Top)
  const unit3Spring = createSpring(5);  // Bottom
  const unit2Spring = createSpring(10); // Middle
  const unit1Spring = createSpring(15); // Top

  // 2. Badge Pop
  const badgeSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 10, stiffness: 120, mass: 0.8 },
  });

  // 3. Text Fade & Slide
  const textOpacity = interpolate(frame, [30, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textSlide = interpolate(frame, [30, 45], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });

  // Helper styles for server units
  const serverUnitStyle: React.CSSProperties = {
    width: unitWidth,
    height: unitHeight,
    backgroundColor: primaryColor,
    borderRadius: unitHeight * 0.3,
    position: "absolute",
    left: (iconSize - unitWidth) / 2,
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end", // Lights on right
    paddingRight: unitWidth * 0.1,
    boxShadow: `0px 4px 10px rgba(0,0,0,0.3)`,
  };

  const lightStyle: React.CSSProperties = {
    width: unitHeight * 0.3,
    height: unitHeight * 0.3,
    borderRadius: "50%",
    backgroundColor: "rgba(255,255,255,0.1)", // Dim light
    marginLeft: unitWidth * 0.03,
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Main Container */}
      <div
        style={{
          position: "relative",
          width: iconSize,
          height: iconSize,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Top Unit */}
        <div
          style={{
            ...serverUnitStyle,
            top: (iconSize - (unitHeight * 3 + unitGap * 2)) / 2,
            transform: `scale(${unit1Spring})`,
          }}
        >
          <div style={lightStyle} />
          <div style={lightStyle} />
        </div>

        {/* Middle Unit */}
        <div
          style={{
            ...serverUnitStyle,
            top: (iconSize - (unitHeight * 3 + unitGap * 2)) / 2 + unitHeight + unitGap,
            transform: `scale(${unit2Spring})`,
          }}
        >
           <div style={lightStyle} />
           <div style={lightStyle} />
        </div>

        {/* Bottom Unit */}
        <div
          style={{
            ...serverUnitStyle,
            top: (iconSize - (unitHeight * 3 + unitGap * 2)) / 2 + (unitHeight + unitGap) * 2,
            transform: `scale(${unit3Spring})`,
          }}
        >
           <div style={lightStyle} />
           <div style={lightStyle} />
        </div>

        {/* Notification Badge */}
        <div
          style={{
            position: "absolute",
            top: iconSize * 0.05,
            right: iconSize * 0.05,
            width: badgeSize,
            height: badgeSize,
            backgroundColor: accentColor,
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${badgeSpring})`,
            boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
            zIndex: 10,
          }}
        >
          <span
            style={{
              color: "#ffffff",
              fontSize: badgeSize * 0.5,
              fontWeight: 700,
              lineHeight: 1,
            }}
          >
            {badgeText}
          </span>
        </div>
      </div>

      {/* Label Text */}
      <div
        style={{
          marginTop: iconSize * 0.1,
          opacity: textOpacity,
          transform: `translateY(${textSlide}px)`,
          textAlign: "center",
        }}
      >
        <h1
          style={{
            color: textColor,
            fontSize: iconSize * 0.20,
            fontWeight: 700,
            margin: 0,
            letterSpacing: "-0.02em",
          }}
        >
          {labelText}
        </h1>
      </div>
    </AbsoluteFill>
  );
};

export default SystemNotification;